TEXTS = {language: {key: row[index] for key, row in _ROWS.items()}
         for index, language in enumerate(LANGUAGES)}


def detail_text(key: str, language: str = "fr", **parameters) -> str:
    return TEXTS.get(language, TEXTS["en"])[key].format(**parameters)
